export type IframeRenderMode = 'iframe-js' | 'static-html' | 'trusted-native';
export type SmartCardResourceKind = 'image' | 'style' | 'script' | 'font' | 'other';
export type SmartCardImmersiveTheme = {
  backgroundColor?: string;
  foregroundColor?: string;
  isDark?: boolean;
};
export type SmartCardViewportContext = NonNullable<CharacterSmartCardContext['viewport']>;
export type SmartCardRenderPart =
  | { type: 'html'; content: string }
  | { type: 'markdown'; content: string };

export interface SmartCardResource {
  url: string;
  sourceUrl: string;
  kind: SmartCardResourceKind;
  priority: 'high' | 'deferred';
  index: number;
}

export interface SmartCardResourcePlan {
  preconnectOrigins: string[];
  high: SmartCardResource[];
  deferred: SmartCardResource[];
}

export interface RgbaColor {
  r: number;
  g: number;
  b: number;
  a: number;
}

export interface SmartCardInspectTarget {
  id: string;
  tag: string;
  text: string;
  selector: string;
  role?: string;
  rect: {
    x: number;
    y: number;
    width: number;
    height: number;
  };
}

export type SmartCardAction =
  | { type: 'sendMessage'; content: string }
  | { type: 'triggerGeneration'; content?: string; awaitResult?: boolean }
  | { type: 'close' }
  | { type: 'setChatMessage'; content: string; index?: number; messageId?: string | number | null; options?: Record<string, unknown> }
  | { type: 'setInputDraft'; content: string }
  | { type: 'scrollChatToBottom' }
  | {
      type: 'request';
      requestId: string;
      action: string;
      payload?: Record<string, unknown>;
      respond: (response: { ok: boolean; result?: unknown; error?: string }) => void;
    }
  | { type: 'diagnostic'; diagnostic: SmartCardCompatDiagnostic }
  | { type: 'refresh' }
  | { type: 'inspectElement'; target: SmartCardInspectTarget }
  | { type: 'log'; level?: string; message?: string }
  | { type: 'error'; message?: string };
